<script lang="ts">
 import {createEventDispatcher} from 'svelte';import hljs from 'highlight.js/lib/core';
 import javascript from 'highlight.js/lib/languages/javascript';import python from 'highlight.js/lib/languages/python';import typescript from 'highlight.js/lib/languages/typescript';import json from 'highlight.js/lib/languages/json';import bash from 'highlight.js/lib/languages/bash';import xml from 'highlight.js/lib/languages/xml';import css from 'highlight.js/lib/languages/css';import sql from 'highlight.js/lib/languages/sql';
 import {csvPreview,artifactLanguage,artifactFilename,downloadArtifact} from './artifact-utils';
 hljs.registerLanguage('javascript',javascript);hljs.registerLanguage('python',python);hljs.registerLanguage('typescript',typescript);hljs.registerLanguage('json',json);hljs.registerLanguage('bash',bash);hljs.registerLanguage('xml',xml);hljs.registerLanguage('css',css);hljs.registerLanguage('sql',sql);
 export let code='';export let language='';export let index=1;export let allowOpen=false;
 const dispatch=createEventDispatcher();let raw=false,notice='';
 $: lang=artifactLanguage(language);$: filename=artifactFilename(lang,index);$: csv=lang==='csv'?csvPreview(code):null;
 $: highlighted=lang!=='csv'&&code.length<100000&&hljs.getLanguage(lang)?hljs.highlight(code,{language:lang,ignoreIllegals:true}).value:'';
 async function copy(){try{await navigator.clipboard.writeText(code);notice='Copied';}catch{notice='Copy unavailable. Select the text to copy.';}}
</script>
<section class="artifact" aria-label={filename}>
 <header><div class="identity"><span class="file-icon" aria-hidden="true">{lang==='csv'?'▦':'‹›'}</span><span><strong>{filename}</strong><small>{lang==='csv'?'CSV spreadsheet':lang==='text'?'Plain text':lang}</small></span></div><div class="actions">{#if csv}<button type="button" aria-pressed={!raw} on:click={()=>raw=!raw}>{raw?'Table preview':'Raw CSV'}</button>{/if}<button type="button" on:click={copy} aria-label={'Copy '+filename}>Copy</button><button type="button" on:click={()=>downloadArtifact(code,filename)}>Download</button>{#if allowOpen}<button class="open" type="button" on:click={()=>dispatch('open',{code,language:lang,filename,index})}>Open editor ↗</button>{/if}</div></header>
 {#if csv&&!raw}<!-- svelte-ignore a11y-no-noninteractive-tabindex --><div class="table-scroll" tabindex="0" role="region" aria-label="CSV table preview"><table><thead><tr>{#each csv.headers as header,i}<th scope="col">{header||'Column '+(i+1)}</th>{/each}</tr></thead><tbody>{#each csv.rows as row}<tr>{#each csv.headers as _,i}<td>{row[i]||''}</td>{/each}</tr>{/each}</tbody></table>{#if !csv.headers.length}<p class="empty">This CSV is empty.</p>{/if}</div><footer><span>{csv.totalRows} data {csv.totalRows===1?'row':'rows'} · {csv.headers.length} preview columns</span>{#if csv.truncated}<span>First 100 rows shown · Download for the complete file</span>{/if}{#if csv.malformed}<span>Incomplete quoted value · Raw CSV is preserved</span>{/if}</footer>
 {:else}<!-- svelte-ignore a11y-no-noninteractive-tabindex --><pre tabindex="0" aria-label={lang+' source code'}><code>{#if highlighted}{@html highlighted}{:else}{code}{/if}</code></pre>{/if}
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}
</section>
<style>
.artifact{white-space:normal;margin:16px 0;border:1px solid #dce5f2;border-radius:12px;background:#fff;box-shadow:0 3px 12px #16345b05;overflow:hidden;min-width:0;max-width:100%;color:#24344d;font-size:12px;line-height:1.5}header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;background:#f7f9fd;border-bottom:1px solid #e2e8f0;flex-wrap:wrap}.identity{display:flex;align-items:center;gap:10px;min-width:0}.identity strong{display:block;font-size:12px;font-weight:650}.identity small{display:block;color:#71809a;font-size:10px;text-transform:uppercase;letter-spacing:.4px}.file-icon{display:grid;place-items:center;width:30px;height:32px;background:#e8f0ff;color:#2563eb;border-radius:7px;font:600 19px ui-monospace,monospace}.actions{display:flex;flex-wrap:wrap;gap:5px}button{border:1px solid #dfe6f1;border-radius:6px;background:#fff;color:#435671;font:inherit;font-size:11px;padding:5px 8px;cursor:pointer}button:hover{border-color:#93b4ff;background:#eef4ff}.open{color:#2563eb}button:focus-visible,pre:focus-visible,.table-scroll:focus-visible{outline:2px solid #2563eb;outline-offset:-2px}pre{white-space:pre;overflow:auto;max-height:480px;padding:18px;margin:0;tab-size:2;background:#fbfcff;color:#26354b;font:12px/1.8 ui-monospace,SFMono-Regular,Consolas,monospace}code{font:inherit}.table-scroll{overflow:auto;max-height:400px}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th{background:#eef4ff;color:#294d80;font-weight:650;position:sticky;top:0;z-index:1}td,th{padding:10px 14px;border-bottom:1px solid #edf1f7;border-right:1px solid #edf1f7;min-width:110px;max-width:400px;white-space:pre-wrap;overflow-wrap:anywhere}tbody tr:nth-child(even){background:#fafcff}footer{display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap;padding:9px 14px;font-size:10px;color:#71809a;background:#f8faff}.notice,.empty{padding:8px 14px;margin:0;font-size:11px;color:#4a6485}
.artifact :global(.hljs-keyword),.artifact :global(.hljs-selector-tag){color:#7c3aed}.artifact :global(.hljs-string),.artifact :global(.hljs-attr){color:#087f5b}.artifact :global(.hljs-comment){color:#7b8799;font-style:italic}.artifact :global(.hljs-number),.artifact :global(.hljs-literal){color:#b45309}.artifact :global(.hljs-title),.artifact :global(.hljs-built_in){color:#2563eb}.artifact :global(.hljs-variable),.artifact :global(.hljs-params){color:#334155}
@media(max-width:600px){header{padding:10px;gap:10px}.actions{width:100%}button{min-height:34px}.artifact{margin:12px 0}pre{padding:12px;font-size:11px}td,th{padding:9px 10px}}
</style>
